preConditionHook:
// THE PRIOR BAR WAS AN OUTSIDE BAR AND THE ALWAYS-IN DIRECTION IS NOT WITH
// THE TRADE. Brooks allows only the WITH-TREND breakout of an outside bar, so
// the rule is stated in the permitting sense and the pane ANDs it in: the long
// side asks that the always-in direction is not already long.
//
// OUTSIDE BAR is the strict two-sided engulf that OutsideOutsidePattern uses,
// read at lag 1: high[1] > high[2] and low[1] < low[2]. Strict on both sides,
// as the source writes it -- an equal high or equal low is not an engulf here.
//
// ALWAYS-IN DIRECTION, the standing corpus decision, inlined here because no
// rule file carries it (same block as TrendDurationBars): the direction FLIPS
// on consecutiveBars consecutive STRONG TREND BARS -- body at least
// bodyFraction of the bar's own range and BOTH tails no more than tailFraction
// of it -- holds until the opposite flip, and is UNDEFINED (aiDir = 0) until
// the first flip ever. The test is `aiDir != 1`, so an UNDEFINED direction
// counts as "not long" and the rule passes: before any flip Brooks has no
// always-in read either, and the merged pseudocode says != +1, not == -1.
//
// The flip is written as two guarded blocks and a flipped flag rather than an
// else-if chain, so the twin is statement for statement. A bar cannot satisfy
// both branches, so the flag only prevents a double count.
//
// The all-of-N loop starts true and lets any failing bar clear the flag --
// StrongTrendBarRun's arrangement -- so the loop runs unconditionally and
// EasyLanguage's lack of short-circuiting cannot matter. The flags are class
// members and persist across bars, so both are reset at the top.
//
// Products, not quotients: EasyLanguage raises a runtime divide-by-zero and a
// zero-range bar is legal data.
//
// Deepest bar touched: max(2, consecutiveBars - 1).
allBull = true;
allBear = true;
for (int k = 0; k < (int)consecutiveBars; ++k) {
    rng = high[k] - low[k];
    if (el_le(close[k], open[k])) allBull = false;
    if (el_lt(close[k] - open[k], bodyFraction * rng)) allBull = false;
    if (el_gt(high[k] - close[k], tailFraction * rng)) allBull = false;
    if (el_gt(open[k] - low[k], tailFraction * rng)) allBull = false;
    if (el_ge(close[k], open[k])) allBear = false;
    if (el_lt(open[k] - close[k], bodyFraction * rng)) allBear = false;
    if (el_gt(close[k] - low[k], tailFraction * rng)) allBear = false;
    if (el_gt(high[k] - open[k], tailFraction * rng)) allBear = false;
}
flipped = false;
if (allBull && aiDir != 1) {
    aiDir = 1;
    flipped = true;
}
if (allBear && aiDir != -1 && flipped == false) {
    aiDir = -1;
    flipped = true;
}
outsideOne = el_gt(high[1], high[2]) && el_lt(low[1], low[2]);
// aiDir is an integer STATE, not a price, so its comparison is exact and must
// not go through el_gt; it lands in a local because a rule CONDITION may not
// carry a raw relational operator.
fireLong = outsideOne && (aiDir != 1);
fireShort = outsideOne && (aiDir != -1);
